/* Riznica recepata – proširenje (domaća i svetska kuhinja, deserti, namazi).
 * Kratak zapis: [id, naziv, ikona, obroci (d=doručak r=ručak v=večera u=užina), vrsta, min, porcije, kcal/porc, proteini/porc,
 *               'Namirnica:količina jedinica:napomena|…', 'Korak.|Korak.']  */
'use strict';
const RTYPES = { corba: '🍲 Čorbe i supe', meso: '🥩 Meso', piletina: '🍗 Piletina', riba: '🐟 Riba', testenina: '🍝 Testenine i žitarice',
  povrce: '🥦 Povrće i variva', salata: '🥗 Salate', pita: '🥧 Pite i peciva', dorucak: '🍳 Doručak', desert: '🍰 Deserti', namaz: '🫙 Namazi i užine' };
const MEAL_CODE = { d: 'dorucak', r: 'rucak', v: 'vecera', u: 'uzina' };
function parseRecipes(rows) {
  return rows.map(([id, name, icon, meals, type, min, serv, kcal, prot, ing, steps]) => ({
    id, name, icon, type, min, serv, kcal, prot,
    meal: meals.split('').map((c) => MEAL_CODE[c]).filter(Boolean),
    ing: ing.split('|').map((x) => {
      const [n, qu = '', note = ''] = x.split(':').map((t) => t.trim());
      const m = qu.match(/^([\d.]+)\s*(\w+)$/);
      return m ? [n, +m[1], m[2], note] : [n, null, '', note || qu];
    }),
    steps: steps.split('|').map((t) => t.trim()).filter(Boolean),
  }));
}

