// ---- vrsta za starije recepte (na osnovu sastojaka i naziva) i ponovno računanje oznaka
for (const r of RECIPES) {
  if (!r.type) {
    const n = r.name.toLowerCase(), ing = r.ing.map(([x]) => x);
    const has = (S) => ing.some((x) => S.has(x));
    r.type = /čorba|supa|tarator/.test(n) ? 'corba'
      : /pita|zeljanica|krompiruša|proja|kačamak|popara/.test(n) ? 'pita'
      : /salata|šopska|kaprese/.test(n) ? 'salata'
      : /sendvič|wrap|tost|smuti|šejk|jogurt|ovsen|omlet|kajgana|jaja|fritata|palačinke|griz|musli|kaša/.test(n) && r.meal.includes('dorucak') ? 'dorucak'
      : has(ING_FISH) ? 'riba'
      : ing.some((x) => /^Pileć|^Pileći|Ćuretina|Piletina/.test(x)) ? 'piletina'
      : has(ING_MEAT) ? 'meso'
      : ing.some((x) => ['Špagete', 'Testenina (penne)', 'Makarone', 'Pirinač', 'Kinoa', 'Kus-kus', 'Heljda'].includes(x)) ? 'testenina'
      : r.meal.length === 1 && r.meal[0] === 'uzina' ? 'namaz'
      : 'povrce';
  }
  const names = r.ing.map(([x]) => x), has = (S) => names.some((x) => S.has(x));
  r.f = { meat: has(ING_MEAT), red: has(ING_RED), processed: has(ING_PROCESSED), fish: has(ING_FISH), dairy: has(ING_DAIRY_EGG), refined: has(ING_REFINED), good: has(ING_GOOD) };
  r.f.posno = !r.f.meat && !r.f.fish && !r.f.dairy;
  r.f.posnoRiba = !r.f.meat && !r.f.dairy;
  r.f.vege = !r.f.meat && !r.f.fish;
  r.tags = [r.f.posno ? 'posno' : r.f.posnoRiba ? 'posno-riba' : '', r.f.vege ? 'vege' : ''].filter(Boolean);
}
